import{z as i,x as l,o as e,c as s,q as t,j as n,D as E,d as B,s as o,S as A}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"期权做市收束","description":"","frontmatter":{"title":"期权做市收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/omm-map.md","filePath":"quant/omm-map.md","lastUpdated":1791063341000}'),m={name:"quant/omm-map.md"};function d(h,a,u,p,f,D){const r=l("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="期权做市收束" tabindex="-1">期权做市收束 <a class="header-anchor" href="#期权做市收束" aria-label="Permalink to &quot;期权做市收束&quot;">​</a></h1><div class="epigraph"><p>做市台没有魔法：一条可审计的账、一张有口径的曲线、一套事先写好的规则；深化课的全部内容，是把这三样从口号变成字段。</p><footer>—— 据 Hull, Options, Futures, and Other Derivatives；Gatheral, The Volatility Surface；运营整合据做市实务整理</footer></div><p><a href="/quant/omm-mark-disputes">上一课</a>把「值多少」收进仲裁流程，本课程到此收束。九课走了一条从地基到屋檐的路：三个簿记课立账本，五个定价与对冲课管日常，本课把它们合回一张图，并标出与已修课程的接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单课各讲一件事，合起来要回答一个问题：做市台的每个动作能否从<strong>成交层追溯到限额层</strong>，中途不经过任何人的记忆。一笔客户单进来：报价来自 <a href="/quant/omm-curve-maintenance">quoted 曲线</a> 的参数与偏移；成交落进 <a href="/quant/omm-book-layering">分层账本</a> 的手层，带成交隐波；仓位折进 <a href="/quant/omm-vol-position-ledger">期限桶</a>，进了 <a href="/quant/omm-greeks-limits">情景限额</a> 的网格；Delta 缺口交给 <a href="/quant/omm-hedge-execution">执行规则表</a>，滑点按到达价记账；隔夜的 <a href="/quant/omm-vanna-charm-daily">时钟与波动漂移</a> 排进晨会；日历上的 <a href="/quant/omm-event-positioning">事件</a> 决定今天的档级；估值冲突归 <a href="/quant/omm-mark-disputes">仲裁层级</a>。任一环节断了链——记号不统一、桶归属缺失、滑点不入账——下游就会用猜补齐，而猜是做市台最贵的原料。</p><p><span class="marginnote">直觉类比：这条链像物流单号系统——包裹每过一站扫码留痕，丢件时能立刻定位在哪一站消失。做市台的每笔风险也要能从报价追到限额；哪一站「只有人记得、没有记录」，件就是在那里丢的。</span></p><p><span class="marginnote">这条链的实用版本是审计三问：这个数字从哪来、谁改过、依据哪条规则。到期周复盘里，「减仓为什么先平这一档」的答案若是人名而不是规则条款，链条在那里就已经断了。</span></p>',7)),(e(),n(A,null,{default:E(()=>[o(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22quoted%20%E6%9B%B2%E7%BA%BF%20%E5%8F%82%E6%95%B0%E5%8A%A0%E5%81%8F%E7%A7%BB%22%5D%20--%3E%20F%5B%22%E6%88%90%E4%BA%A4%20%E5%9B%9E%E6%8A%A5%22%5D%0A%20%20F%20--%3E%20L%5B%22%E6%89%8B%E5%B1%82%E6%89%B9%E6%AC%A1%20%E5%B8%A6%E6%88%90%E4%BA%A4%E9%9A%90%E6%B3%A2%22%5D%0A%20%20L%20--%3E%20V%5B%22%E6%9C%9F%E9%99%90%E6%A1%B6%20Vega%20%E4%B8%8E%E6%9C%AA%E5%AE%9E%E7%8E%B0%E7%9B%88%E4%BA%8F%22%5D%0A%20%20V%20--%3E%20G%5B%22%E6%83%85%E6%99%AF%E9%99%90%E9%A2%9D%20%E7%BD%91%E6%A0%BC%22%5D%0A%20%20G%20--%3E%20H%5B%22%E5%AF%B9%E5%86%B2%E6%89%A7%E8%A1%8C%20%E5%88%B0%E8%BE%BE%E4%BB%B7%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20H%20--%3E%20D%5B%22vanna%20charm%20%E9%9A%94%E5%A4%9C%E6%8E%92%E7%8F%AD%22%5D%0A%20%20D%20--%3E%20E%5B%22%E4%BA%8B%E4%BB%B6%E5%8F%B0%E8%B4%A6%20%E6%A1%A3%E7%BA%A7%22%5D%0A%20%20E%20--%3E%20M%5B%22%E7%9B%AF%E5%B8%82%E4%B8%8E%E4%BB%B2%E8%A3%81%20%E5%B1%82%E7%BA%A7%E8%A1%A8%22%5D%0A%20%20M%20--%3E%7C%22%E5%85%88%E4%BE%8B%E4%B8%8E%E5%87%8F%E8%AE%B0%E5%9B%9E%E5%86%99%22%7C%20Q%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把收束写成一张对照表：每课交付一个<strong>字段</strong>或<strong>规则</strong>，而不是一个知识点。账本课交付批次与开平指定；波动账本课交付桶归属与标记隐波；限额课交付情景网格与软硬分级；曲线课交付 TTL、正则与三档快市动作；执行课交付参与率上限与到达价台账；事件课交付台账与档级；vanna / charm 课交付偏移预留与晨会排班；仲裁课交付层级表与 IPV。验收一条链是否活着，用最普通的审计问句：这个数字从哪来、谁改过、依据哪条规则——三个答案都指向文件而不是人，链就是活的。</p><p>与已修课程的接口同样要钉死：曲面几何与 <a href="/quant/svi-ssvi">无套利参数化</a> 是曲线课的输入，<a href="/quant/delta-hedge-freq">Delta 对冲频率</a> 与 <a href="/quant/discrete-hedge-error">离散对冲误差</a> 是执行课的理论层，<a href="/quant/vanna-volga">Vanna / Volga 三点</a> 与 <a href="/quant/higher-greeks">高阶希腊</a> 是漂移课的工具箱，<a href="/quant/gamma-scalping-pnl">Gamma scalping 恒等式</a> 与 <a href="/quant/risk-reversal-skew">偏度溢价</a> 解释这台子赚的是什么钱，<a href="/quant/vix-term-structure-trade">VIX 期限结构</a> 把桶语言接到指数产品。深化课不重复它们，只把理论装进流程的螺丝孔。</p><p><span class="marginnote">数字实例：审计三问的一次合格回答长这样——「这个 Vega 数字来自 9 月桶、标记隐波 32%（文件）；由曲线管线 14:05 自动更新（系统）；依据 TTL 规则第 3 条（规则）」。三个答案都指向文件与人名无关，这条链才算活着。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>课程内部有一条机制主线：<strong>信息只进不丢，规则先于裁量</strong>。账本层不丢手数与成本，桶不丢期限与分位，滑点台账不丢执行损耗，仲裁先例不丢裁定依据——每一层保留的信息，都是下游某个流程免于猜测的代价。反过来，凡是靠记忆与盘感补位的环节（哪个桶该减、哪笔报价算数、漂移留给谁补），都会在压力大、人最累的那天变成事故。做市业务的其他课程讲的是「如何赚」，本课程讲的是「如何活得久且说得清」：收益来自曲线与存货，生存来自账、限、裁三条硬规则。</p>',6)),(e(),n(A,null,{default:E(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20X1%5B%22%E8%AE%B0%E5%8F%B7%E4%B8%8D%E7%BB%9F%E4%B8%80%22%5D%20--%3E%20Y1%5B%22%E6%A1%B6%E5%BD%92%E5%B1%9E%E7%BC%BA%E5%A4%B1%22%5D%0A%20%20X2%5B%22%E6%BB%91%E7%82%B9%E4%B8%8D%E5%85%A5%E8%B4%A6%22%5D%20--%3E%20Y2%5B%22%E6%89%A7%E8%A1%8C%E8%A7%84%E5%88%99%E6%B2%A1%E6%B3%95%E6%A0%A1%E5%87%86%22%5D%0A%20%20X3%5B%22%E5%85%88%E4%BE%8B%E4%B8%8D%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20Y3%5B%22%E4%BB%B2%E8%A3%81%E9%87%8D%E6%96%B0%E5%90%B5%E4%B8%80%E9%81%8D%22%5D%0A%20%20Y1%20--%3E%20Z%5B%22%E4%B8%8B%E6%B8%B8%E7%94%A8%E7%8C%9C%E8%A1%A5%E9%BD%90%22%5D%0A%20%20Y2%20--%3E%20Z%0A%20%20Y3%20--%3E%20Z%0A%20%20Z%20--%3E%20W%5B%22%E7%8C%9C%E6%98%AF%E5%81%9A%E5%B8%82%E5%8F%B0%E6%9C%80%E8%B4%B5%E7%9A%84%E5%8E%9F%E6%96%99%22%5D%0A%20%20W%20--%3E%20V%5B%22%E5%8E%8B%E5%8A%9B%E5%A4%A7%20%E4%BA%BA%E6%9C%80%E7%B4%AF%E7%9A%84%E9%82%A3%E5%A4%A9%20%E5%8F%98%E6%88%90%E4%BA%8B%E6%95%85%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程刻意没有覆盖三块。其一，策略层：报价偏移与 <a href="/quant/avellaneda-stoikov">库存理论</a> 的最优参数在哪里，属于做市策略而非做市运营。其二，制度化前线：义务做市的协议细节与监管口径，各辖区不同。其三，前沿：<a href="/quant/rl-market-making">强化学习做市</a> 把报价写成序贯决策，<a href="/quant/menkveld-hft-mm">高频做市实证</a> 给出行业基准——它们检验的仍是本课程的地基：账本、限额与执行规则不变，变的是生成报价的那一层。跨品种组合、场外簿记与清算也各有专课，此处不展开。</p><p><span class="marginnote">常见误区：初学者容易以为做市台的核心竞争力是「预测准」。本课程的答案相反：收益来自曲线与存货，生存来自账、限、裁三条硬规则——预测只决定多赚一点，断链却能让台子一夜说不清自己持有过什么。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>九课一条链：报价、落账、分桶、限额、执行、漂移、事件、仲裁，环环可追溯。</li><li>每课交付字段或规则；验收标准是「数字从哪来、谁改过、依据哪条」三问有文件答案。</li><li>机制主线：信息只进不丢，规则先于裁量；记忆补位的环节就是事故的地址。</li><li>与基础课的分工：几何、频率、恒等式在先修课，本课程把它们装进流程。</li><li>未覆盖的策略层、监管细节与 RL 前沿各有专课，接口已标出。</li><li>出处：Hull, <em>Options, Futures, and Other Derivatives</em>；Gatheral, <em>The Volatility Surface</em>；整合口径据期权做市运营实务整理。</li></ul>',5))])}const c=i(m,[["render",d]]);export{_ as __pageData,c as default};
